    /** 与音源页一致的组合过滤；城市与类型只在 FM 页生效。 */
    fun filter(
        international: Boolean,
        region: String = "全部",
        city: String = "全部",
        type: String = "全部",
        query: String = ""
    ): List<RadioStation> {
        val keyword = query.trim().lowercase()
        // 国内外合并展示；international 仅保留给旧调用方，不再隐藏另一目录。
        return (fmStations + internationalStations).distinctBy { it.id }.filter { station ->
            (region == "全部" || station.region == region) &&
                (city == "全部" || station.city == city) &&
                (type == "全部" || station.type == type) &&
                (keyword.isEmpty() || listOf(station.name, station.region, station.city, station.type)
                    .any { it.lowercase().contains(keyword) })
        }
    }
